-- Contrôles après la chaîne complète 0134 → 0137 → 0146 → 0145 → 0144.
select 'C1 toutes les migrations présentes', to_regclass('public.bellaia_candidatures') is not null and to_regclass('public.bellaia_suspensions') is not null and to_regclass('public.bellaia_invitations') is not null and to_regclass('public.bellaia_repertoire') is not null and to_regclass('public.bsh_hotes_nominations') is not null and exists (select 1 from pg_indexes where tablename = 'bellaia_roles' and indexdef ilike 'CREATE UNIQUE INDEX % (user_id, role, COALESCE(organisation_id,%');
select 'C2 a_permission de 0136 conservée (suspensions prises en compte), non écrasée par 0144/0145', pg_get_functiondef('public.a_permission(text,text)'::regprocedure) like '%est_suspendu%';
select 'C3 journal des droits : auteur enregistré (0145) et toujours branché sur les suspensions (0136)', pg_get_functiondef('public.journaliser_droits()'::regprocedure) like '%auth.uid()%' and exists (select 1 from pg_trigger where tgname = 'trg_journal_suspensions');
select 'C4 acceptation d''invitation (0137) compatible avec l''unicité (on conflict do nothing)', pg_get_functiondef(p.oid) like '%Invitation%on conflict do nothing%' from pg_proc p where p.proname = 'accepter_invitation' limit 1;
select 'C5 doublons de fonctions en base après la chaîne', (select count(*) from (select user_id, role, organisation_id from public.bellaia_roles group by 1,2,3 having count(*) > 1) d) = 0;
-- 0146 : missions cloisonnées par pôle (comptes fictifs E : missions VILDOR ; G : missions tout Bellaïa)
\set E '00000000-0000-0000-0000-0000000000e1'
\set G2 '00000000-0000-0000-0000-0000000000e2'
insert into auth.users(id, email) values (:'E','e@essai.invalid'), (:'G2','g2@essai.invalid') on conflict do nothing;
insert into public.bellaia_permissions(user_id, permission, univers) values (:'E','missions.gerer','VILDOR'), (:'G2','missions.gerer','*');
insert into public.bellaia_missions(id, titre, univers) values ('90000000-0000-0000-0000-000000000001','Macarons Noël','VILDOR'), ('90000000-0000-0000-0000-000000000002','Menu du jour','FOOD');
select 'M1 permission VILDOR : voit la mission Vil''Dor, pas la mission Bella''Food', pg_temp.compte(:'E', $q$select count(*) from bellaia_missions where id in ('90000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000002')$q$) = 1 and pg_temp.compte(:'E', $q$select count(*) from bellaia_missions where titre = 'Menu du jour'$q$) = 0;
select 'M2 permission « tout Bellaïa » : voit les deux', pg_temp.compte(:'G2', $q$select count(*) from bellaia_missions where id in ('90000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000002')$q$) = 2;
select 'M3 permission VILDOR : crée une mission Vil''Dor, création Bella''Food refusée', pg_temp.essai(:'E', $q$insert into bellaia_missions(titre, univers) values ('Coffrets', 'VILDOR')$q$) = 'accepté' and pg_temp.essai(:'E', $q$insert into bellaia_missions(titre, univers) values ('Pirate', 'FOOD')$q$) = 'refusé';
select 'M4 permission VILDOR : ne peut pas déplacer une mission vers un autre pôle', pg_temp.compte(:'E', $q$with u as (update bellaia_missions set univers = 'FOOD' where id = '90000000-0000-0000-0000-000000000001' returning 1) select count(*) from u$q$) = -1 or pg_temp.compte(:'E', $q$select count(*) from bellaia_missions where id = '90000000-0000-0000-0000-000000000001' and univers = 'VILDOR'$q$) = 1;
select 'M5 fil de discussion : lecture et écriture limitées au pôle', pg_temp.essai(:'E', $q$insert into bellaia_missions_fil(mission_id, auteur, type, texte) values ('90000000-0000-0000-0000-000000000001', auth.uid(), 'commentaire', 'ok')$q$) = 'accepté' and pg_temp.essai(:'E', $q$insert into bellaia_missions_fil(mission_id, auteur, type, texte) values ('90000000-0000-0000-0000-000000000002', auth.uid(), 'commentaire', 'intrus')$q$) = 'refusé';
select 'M6 livrable : refusé sur une mission d''un autre pôle', pg_temp.essai(:'E', $q$select mission_ajouter_livrable('90000000-0000-0000-0000-000000000002', null, 'x')$q$) = 'refusé' and pg_temp.essai(:'E', $q$select mission_ajouter_livrable('90000000-0000-0000-0000-000000000001', null, 'Photos')$q$) = 'accepté';
